definition.script:
pipeline {
  agent any
  stages {
    stage('Checkout-ish') {
      steps { echo 'In a real job this stage would check out SCM.' }
    }
    stage('Build') {
      steps { sh 'echo Building... && sleep 1' }
    }
    stage('Test') {
      steps { sh 'echo Running tests... && sleep 1' }
    }
    stage('Package') {
      steps { echo 'Packaging artifact.' }
    }
  }
  post {
    always { echo 'This pipeline is a Jenkinsfile, run by a controller you operate.' }
  }
}
